// The Forth section's playground (forth/, generated by
// doc/manual/gen/genforth.py): the real Strata Forth image, build/forth.stx,
// in the WebAssembly emulator. It shares the play page's machinery rather
// than copying it: the worker (../play/worker.js, which owns the emulator
// and speaks the protocol documented at its top), the module
// (../play/strata-emu.wasm), the images and the Forth demos all come from
// ../play/. This file only moves bytes, like play.js: console output to the
// terminal, keys and "Try" examples to the worker, framebuffer rows to the
// canvas.
"use strict";
(function () {
  // tools/web-stamp.sh puts the build id here; every asset URL carries it
  const BUILD = "__BUILD__";
  const V = "?v=" + BUILD;
  const PLAY = "../play/";
  const params = new URLSearchParams(location.search);
  const ARGS = [params.get("jit") === "0" ? "-j" : "-J", "-c", "8", "-r", "640x400", "forth.stx"];

  const $ = (id) => document.getElementById(id);
  const pg = $("pg"), toggle = $("pg-toggle"), statusEl = $("pg-status");
  const screenBox = $("pg-screen"), canvas = $("pg-canvas"), screenBtn = $("pg-screen-b");
  const ctx = canvas.getContext("2d");
  const enc = new TextEncoder();
  const wide = () => matchMedia("(min-width: 1280px)").matches;
  const touch = () => matchMedia("(pointer: coarse)").matches;

  // -------------------------------------------------------------- terminal
  const term = new Terminal({
    convertEol: true, cursorBlink: true, scrollback: 5000,
    fontFamily: '"JetBrains Mono", ui-monospace, Menlo, monospace', fontSize: 13,
    theme: {
      background: "#05080f", foreground: "#cfe8ff", cursor: "#ffb347", cursorAccent: "#05080f",
      selectionBackground: "rgba(77, 225, 255, 0.3)",
      black: "#0b1120", red: "#ff6b6b", green: "#5be3a1", yellow: "#ffb347", blue: "#4d8dff",
      magenta: "#c38bff", cyan: "#4de1ff", white: "#cfe8ff",
      brightBlack: "#5b7088", brightRed: "#ff8f8f", brightGreen: "#8af0bf", brightYellow: "#ffd08a",
      brightBlue: "#7fb0ff", brightMagenta: "#dab4ff", brightCyan: "#9bf0ff", brightWhite: "#ffffff",
    },
  });
  const fit = new FitAddon.FitAddon();
  term.loadAddon(fit);
  term.open($("pg-term"));
  function refit() {
    if (!$("pg-term").offsetHeight) return; // the drawer is closed
    try { fit.fit(); } catch (e) { /* not laid out yet */ }
    term.scrollToBottom();
  }
  document.fonts.load('13px "JetBrains Mono"').then(() => document.fonts.ready).then(() => {
    const f = term.options.fontFamily;
    term.options.fontFamily = "monospace";
    term.options.fontFamily = f;
    refit();
  });
  new ResizeObserver(refit).observe($("pg-term"));
  term.writeln("\x1b[36mStrata Forth\x1b[0m in the WebAssembly emulator: type, or press Try on a word.");

  // -------------------------------------------------------------- the machine
  let W = null, stopped = true, pending = "", booted = false, gen = 0;
  let last = { t: 0, steps: 0 };

  let wasmModule = null;
  async function compileWasm() {
    if (wasmModule) return wasmModule;
    try {
      wasmModule = await WebAssembly.compileStreaming(fetch(PLAY + "strata-emu.wasm" + V));
    } catch (e) { // a server without application/wasm
      wasmModule = await WebAssembly.compile(await (await fetch(PLAY + "strata-emu.wasm" + V)).arrayBuffer());
    }
    return wasmModule;
  }
  let image = null;
  function fetchImage() {
    if (!image) image = fetch(PLAY + "images/forth.stx" + V).then((r) => {
      if (!r.ok) throw new Error("images/forth.stx: " + r.status);
      return r.arrayBuffer();
    });
    return image;
  }

  function setStatus(s, isStop) {
    statusEl.textContent = s;
    statusEl.classList.toggle("stopped", !!isStop);
  }

  function post(s) {
    let bytes = [];
    for (const ch of s) for (const b of enc.encode(ch === "\r" ? "\n" : ch)) bytes.push(b);
    if (bytes.length) W.postMessage({ t: "input", data: new Uint8Array(bytes) });
  }
  // Bytes for the console; before the machine is up they wait here.
  function send(s) {
    if (W && !stopped) post(s);
    else { pending += s; boot(); }
  }

  function onWorker(w, m) {
    if (w !== W) return;
    switch (m.t) {
    case "out": term.write(m.data, () => term.scrollToBottom()); break;
    case "paint": paint(m); break;
    case "started":
      last = { t: performance.now(), steps: 0 };
      setStatus("running · bare metal, 8 cores");
      break;
    case "status": {
      const t = performance.now();
      const mips = (m.steps - last.steps) / ((t - last.t) * 1000);
      last = { t, steps: m.steps };
      setStatus(`running · ${m.live}/${m.cores} cores live · ` +
                (mips >= 1 ? `${mips.toFixed(0)} MIPS (${m.jit ? "JIT" : "interpreter"})` : "waiting for input") +
                ` · ${(m.steps / 1e6).toFixed(1)}M instructions`);
      break;
    }
    case "stopped":
      stopped = true;
      setStatus((m.state === 1 ? (m.faulted ? "halted: a core faulted" : "every core halted (bye)")
                 : m.state === 2 ? "deadlock" : "stopped") + " · Reset to boot again", true);
      break;
    case "exit": stopped = true; setStatus(`exited (${m.code}) · Reset`, true); break;
    case "error": stopped = true; setStatus("error: " + m.msg, true); break;
    }
  }

  async function boot() {
    if (booted) return;
    booted = true;
    const my = ++gen;
    setStatus("loading…");
    term.write("\x1bc");
    term.write(`\x1b[2m$ strata-emu ${ARGS.join(" ")}\x1b[0m\n`);
    try {
      const [wasm, img] = await Promise.all([compileWasm(), fetchImage()]);
      if (my !== gen) return;               // Reset meanwhile
      const w = new Worker(PLAY + "worker.js" + V);
      W = w;
      stopped = false;
      w.onmessage = (e) => onWorker(w, e.data);
      w.onerror = (e) => { if (w === W) { stopped = true; setStatus("error: " + (e.message || "the worker failed"), true); } };
      w.postMessage({ t: "start", wasm, files: [{ name: "forth.stx", data: img }], args: ARGS });
      if (pending) { post(pending); pending = ""; }
    } catch (e) {
      booted = false;
      setStatus("error: " + (e && e.message ? e.message : e), true);
    }
  }

  function reset() {
    if (W) W.terminate();
    W = null;
    stopped = true;
    booted = false;
    pending = "";
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    showScreen(false);
    screenSeen = false;
    boot();
  }

  // -------------------------------------------------------------- the screen
  // Changed framebuffer rows, already RGBA. The panel opens at the first
  // paint (the gfx demo); the Screen button shows or hides it.
  let screenSeen = false;
  function showScreen(on) {
    screenBox.hidden = !on;
    screenBtn.setAttribute("aria-pressed", on ? "true" : "false");
    refit();
  }
  function paint(m) {
    if (canvas.width !== m.w || canvas.height !== m.h) { canvas.width = m.w; canvas.height = m.h; }
    if (!screenSeen) { screenSeen = true; showScreen(true); }
    ctx.putImageData(new ImageData(m.data, m.w, m.rows), 0, m.y0);
  }
  screenBtn.addEventListener("click", () => showScreen(screenBox.hidden));

  // -------------------------------------------------------------- the drawer
  function isOpen() { return wide() || pg.classList.contains("open"); }
  function setOpen(on) {
    pg.classList.toggle("open", on);
    toggle.setAttribute("aria-expanded", String(on || wide()));
    toggle.querySelector(".pg-title").textContent = (on || wide() ? "▾" : "▸") + " PLAYGROUND";
    if (on || wide()) { requestAnimationFrame(refit); boot(); }
  }
  toggle.addEventListener("click", () => { if (!wide()) setOpen(!pg.classList.contains("open")); });
  addEventListener("resize", () => setOpen(pg.classList.contains("open")));
  for (const b of document.querySelectorAll("[data-pg-open]"))
    b.addEventListener("click", () => { setOpen(true); term.focus(); });
  setOpen(false);                            // wide: open, and boots now

  // -------------------------------------------------------------- input
  term.onData((d) => { term.scrollToBottom(); send(d); });
  $("pg-reset").addEventListener("click", () => { reset(); if (!touch()) term.focus(); });

  // Try: type the entry's example in, as if typed, followed by Enter
  document.addEventListener("click", (e) => {
    const b = e.target.closest(".try-b");
    if (!b) return;
    if (!isOpen()) setOpen(true);
    send(b.dataset.try.replace(/\r\n?/g, "\n") + "\n");
    b.classList.add("sent");
    setTimeout(() => b.classList.remove("sent"), 600);
    if (!touch()) term.focus({ preventScroll: true });
  });

  // the demos (lang/forth/demos/*.fs, listed by make wasm in demos/index.txt)
  const demos = $("pg-demos");
  fetch(PLAY + "demos/index.txt" + V).then((r) => (r.ok ? r.text() : "")).then((txt) => {
    for (const name of txt.split(/\s+/).filter(Boolean)) {
      const o = document.createElement("option");
      o.value = name;
      o.textContent = name + ".fs";
      demos.appendChild(o);
    }
  });
  demos.addEventListener("change", async () => {
    const name = demos.value;
    demos.value = "";
    if (!name) return;
    if (!isOpen()) setOpen(true);
    const text = await (await fetch(PLAY + "demos/" + name + ".fs" + V)).text();
    send(text.replace(/\r\n?/g, "\n"));
    if (!touch()) term.focus({ preventScroll: true });
  });
})();
